/// Shared `ThrowItem2` payload state. Grenade is the first consumer; Smoke,
/// Poke Ball, Tack, and Mjolnir use the same held-item/throw lifecycle.
#[derive(Clone, Copy, Default)]
pub struct ThrownItem {
    pub active: bool,
    pub id: u32,
    pub owner: usize,
    pub ability: u32,
    pub ability_slot: usize,
    pub ability_generation: u32,
    pub born_tick: u32,
    pub hierarchy_base: u32,
    pub entity: Option<usize>,
    /// A ManualInit performed from a DetPhysics callback joins the collider
    /// registry immediately but cannot enter the already-built manifold set.
    pub callback_registered_tick: u32,
    pub position: Vec2,
    /// The position DetPhysics' broadphase swept this pass, before any
    /// correction moved it.
    pub swept_position: Vec2,
    pub body: Body,
    /// Live DPhysicsCircle/FixTransform scale. `body_scale` is the value the
    /// earlier BoplBody updater has consumed; a late ScaleChanger mutation is
    /// reflected in mass on the following updater pass, as in the source.
    pub scale: Fix,
    pub body_scale: Fix,
    /// DPhysicsCircle's live radius. Scale mutates this incrementally through
    /// `(1 / old_scale) * new_scale`, retaining its fixed-point history.
    pub collider_radius: Fix,
    pub fuse: Fix,
    pub hurt_owner_delay: Fix,
    pub detonates_on_owner: bool,
    pub age: Fix,
    pub launched: bool,
    pub settled: bool,
    pub owner_clear: bool,
    pub settle_position: Vec2,
    /// Ability-specific phase (Mjolnir: 0 outbound, 1 returning).
    pub phase: u8,
    /// Mjolnir's allocation-free equivalent of `HashSet<int> alreadyKilled`.
    pub killed_players: u8,
    /// Shockwave.UpdateSim follows Mjolnir.UpdateSim in runtime hierarchy,
    /// while Shockwave.Init runs before the updater pass. Retain only the
    /// regular-pass impulse until Mjolnir has updated its recall velocity.
    pub pending_gust_impulse: Vec2,
    /// Mine.Init/LateUpdateSim state. Keeping it in the pooled item avoids a
    /// side allocation for every autonomous mine.
    pub random_offset: Fix,
    pub time_since_anticipation: Fix,
    pub prev_chase_dir: Vec2,
    pub prev_rand_vector: Vec2,
    pub prev_velocity_change: Vec2,
    /// The last shake's net move, which the collider only takes at the next Simulate.
    pub pending_shake: Vec2,
    /// Poke Ball capture state. `None` is the ordinary flying/fizzle phase.
    pub capture_victim: Option<usize>,
    pub capture_victim_is_clone: bool,
    pub capture_left: Fix,
    /// `DetPhysics.duplicatedObjects`: Duplicator copies count down from 1800
    /// before ordinary updaters run.
    pub duplicated: bool,
    pub duplicate_lifespan: i32,
    pub duplicate_shake_offset: Vec2,
    /// Player slot whose Magnet currently refreshes this item's Hold(2).
    pub magnet_holder: Option<usize>,
    pub magnet_hold_ticks: i8,
}

