    /// Run Magnet's three state-bearing prefab updater phases in hierarchy
    /// order. Ability.UpdateSim publishes the transform left by MagnetGun,
    /// before the later PlayerBody integration advances it.
    fn magnet_tick(
        &mut self,
        index: usize,
        action: Action,
        movement_input: Vec2,
        data: &data::RolloutData,
        advance_animation: bool,
    ) {
        self.magnet_gun_update(index, action, movement_input, data, advance_animation);
        if self.players[index].active != ActiveAbility::Magnet {
            return;
        }

        // Ability.UpdateSim, hierarchy 3. PlayerPhysics at hierarchy 4 only
        // updates scale for this prefab because ApplyGravity is disabled.
        self.magnet_ability_update_scale(index);
        self.players[index].reported_position = self.players[index].base.position;
        self.players[index].reported_tick = self.tick;

        // MagnetGun's DestroyIfOutsideSceneBounds precedes PlayerBody.
        if self.ability_boundary_kill(index, true) {
            return;
        }

        // PlayerBody.UpdateSim, hierarchy 8.
        self.form_body_step(index);
    }

    fn magnet_ability_update_scale(&mut self, index: usize) {
        let ability_slot = self.players[index].active_slot;
        let scale = self.players[index].player_scale;
        let previous = self.players[index].magnet_prev_scales[ability_slot];
        if scale != previous {
            self.players[index].magnet_firepoint_offsets[ability_slot] *= scale / previous;
            self.players[index].magnet_prev_scales[ability_slot] = scale;
        }
    }

    /// MagnetGun.UpdateSim, hierarchy 2. Pull/pickup callbacks are layered
    /// onto the prepulling/pulling section; this keeps the animation and
    /// movement handoff exact even when the query contains no target.
    fn magnet_gun_update(
        &mut self,
        index: usize,
        action: Action,
        movement_input: Vec2,
        data: &data::RolloutData,
        advance_animation: bool,
    ) {
        let magnet = &data.magnet;
        if advance_animation {
            let state = &mut self.players[index].magnet;
            state.animation_ticks += 1;
            match state.animation {
                0 if state.animation_ticks > magnet.enter_ticks => {
                    // enterPrePull begins a fresh prepull animation while the
                    // state is already prepulling from OnEnterAbility.
                    state.animation = 1;
                    state.animation_ticks = 0;
                }
                1 if state.animation_ticks > magnet.prepull_ticks => {
                    state.phase = 2;
                    state.animation = 2;
                    state.animation_ticks = 0;
                }
                3 if state.animation_ticks > magnet.exit_ticks => {
                    self.exit_magnet(index, false, data);
                    return;
                }
                _ => {}
            }
        }

        let direction = action.direction();
        if direction != Vec2::ZERO {
            self.players[index].magnet.aim = direction.normalized();
        }
        self.players[index].magnet.time_spent_pulling += DT;
        if matches!(self.players[index].magnet.phase, 1..=3)
            && self.players[index].magnet.time_spent_pulling > magnet.max_pull_duration
        {
            let state = &mut self.players[index].magnet;
            state.phase = 4;
            state.animation = 2;
            state.animation_ticks = 0;
            // enterPause changes heldItemState to nothing. BoplBody's own
            // countdown releases its holder on the following updater passes.
            state.held = MagnetHeld::Nothing;
            state.extra_offset = Vec2::ZERO;
        }

        if matches!(self.players[index].magnet.phase, 1 | 2) {
            self.magnet_pull(index, data);
            self.magnet_try_pickup_item(index, data);
        }
        if self.players[index].magnet.phase == 3 {
            self.magnet_update_held_item(index, data);
        }

        let button = 2u8 << self.players[index].active_slot;
        if action.buttons & button == 0 && !self.players[index].magnet.has_fired {
            self.fire_magnet(index, data);
        }

        let invalid_ground = self.players[index].base.grounded
            && (self.players[index].base.velocity.length_squared() > Fix::from_f32(1e-6)
                || self.players[index].base.ground.is_none()
                || self.players[index]
                    .base
                    .ground
                    .and_then(|id| self.platforms.iter().find(|p| p.id == id))
                    .is_none());
        if invalid_ground {
            let slot = self.players[index].active_slot;
            self.players[index].gun_gravity[slot] = Fix::from_f32(0.03);
            self.players[index].base.force_unground(&self.platforms);
        }

        if !self.players[index].base.grounded {
            let gravity_modifier =
                self.players[index].gun_gravity[self.players[index].active_slot];
            let slot = &mut self.players[index];
            let space = slot.base.space;
            crate::player_physics::apply_gravity(
                &mut slot.base.velocity,
                magnet.constants.gravity_accel,
                gravity_modifier,
                magnet.constants.gravity_max_fall_speed,
                space,
            )
            .expect("valid Magnet gravity constants");
            // A held boulder's hitbox is off for the raycasts
            // (MagnetGun.cs:1216-1225).
            let held_boulder = match slot.magnet.held {
                MagnetHeld::Boulder(boulder) if slot.magnet.phase == 3 => {
                    Some(self.macho_boulders[boulder].platform_index)
                }
                _ => None,
            };
            let hidden = held_boulder.filter(|&platform| self.platforms[platform].active);
            if let Some(platform) = hidden {
                self.platforms[platform].active = false;
            }
            let slot = &mut self.players[index];
            slot.base.collision_rays(terrain!(self));
            if let Some(platform) = hidden {
                self.platforms[platform].active = true;
            }
            let slot = &mut self.players[index];
            if slot.base.grounded && slot.magnet.has_fired {
                self.exit_magnet(index, true, data);
                return;
            }
        }
        if self.players[index].base.grounded {
            self.players[index]
                .base
                .move_only(Vec2::ZERO, terrain!(self));
        }

        let slot = &mut self.players[index];
        if !slot.magnet.has_fired {
            slot.base.up = slot.magnet.aim.perp();
            slot.base.rotation = slot.magnet.aim.normalized_angle();
            slot.magnet.body_right = slot.magnet.aim;
            if slot.base.velocity.length() > magnet.max_slow_mo_speed {
                slot.base.velocity = slot.base.velocity.normalized() * magnet.max_slow_mo_speed;
            }
        } else {
            let before = slot.base.velocity;
            crate::player_physics::air_movement(
                &mut slot.base.velocity,
                movement_input.x,
                magnet.constants.air_accel,
                magnet.constants.max_speed,
            )
            .expect("valid Magnet air constants");
            let after = slot.base.velocity;
            slot.base.velocity =
                before * (Fix::ONE - magnet.air_control_blend) + after * magnet.air_control_blend;
        }
        if slot.base.velocity.length() > magnet.constants.max_speed {
            slot.base.velocity = slot.base.velocity.normalized() * magnet.constants.max_speed;
        }
    }

    /// MagnetGun.TryPullItems' rounded-platform branch. The source first
    /// shortens its oriented query box to half of the nearest rounded-wall
    /// ray distance, then applies an immediate off-centre impulse to every
    /// wall in that box. Dynamic item/player branches are handled alongside
    /// their respective pools.
    ///
    /// Every pull below forms its vector the way the source writes it:
    /// `-pullStr * fix3 * vec2` (MagnetGun.cs:527,539,546,558,568,572), which
    /// C# parses as `((-pullStr) * fix3) * vec2` - one scalar product, then one
    /// multiply per component. The port used to write `direction * pull *
    /// strength` and subtract it, which floors each component twice in the
    /// other order and negates the product instead of the scalar. `Fix`
    /// multiply floors, so neither rearrangement is free: with the shipped
    /// constants the two orders differ on essentially every pull, by 1 raw for
    /// pullStr/projectilePullStr/wallPullStr (exact integers, so only the sign
    /// placement bites) and by up to 8 raw for playerPullStr and
    /// MachoSlimePullStr, where the grouping bites as well. Division is
    /// sign-symmetric in this `Fix` (it negates after dividing magnitudes), so
    /// only the multiplies had to move.
    fn magnet_pull(&mut self, index: usize, data: &data::RolloutData) {
        let magnet = &data.magnet;
        let slot = &self.players[index];
        let direction = slot.magnet.aim.normalized_safe();
        if direction == Vec2::ZERO {
            return;
        }
        let firepoint = self.magnet_firepoint(index, data);
        let mut half_length = Fix::from_int(1000);
        let mut nearest = Fix::MAX;
        for platform in self.platforms.iter().filter(|platform| platform.active) {
            if let Some(hit) = platform
                .collider
                .raycast(firepoint, direction)
                .filter(|hit| hit.near <= Fix::from_int(10_000))
                && hit.near < nearest
            {
                nearest = hit.near;
            }
        }
        if nearest != Fix::MAX {
            half_length = nearest / Fix::from_int(2);
        }
        half_length = half_length.max(Fix::from_f64(0.01));
        let half_width = magnet.pull_width.max(Fix::from_f64(0.01));
        let query = OrientedBox::from_basis(
            firepoint + direction * half_length,
            direction,
            Vec2::new(half_length, half_width),
        );
        let multiplier = magnet
            .pull_curve
            .evaluate(slot.magnet.time_spent_pulling / magnet.max_pull_duration);
        let raw_firepoint_offset = slot.magnet_firepoint_offsets[slot.active_slot];
        let ground = slot.base.ground;
        let body_position = slot.base.position;
        let mut changed = false;
        for platform_index in 0..self.platforms.len() {
            if ground == Some(self.platforms[platform_index].id)
                || !self.platforms[platform_index].active
            {
                continue;
            }
            if !box_rounded_overlaps(query, self.platforms[platform_index].collider) {
                continue;
            }
            let position = self.platforms[platform_index].surface.center;
            let application = body_position + direction * (position - body_position).dot(direction);
            let arm = (application - position).normalized_safe();
            self.platform_dynamics[platform_index]
                .body
                .apply_impulse((-magnet.wall_pull_strength * multiplier) * direction, arm);
            changed = true;
        }
        for player_index in 0..self.players.len() {
            if !self.playable(player_index) {
                continue;
            }
            let target = &self.players[player_index];
            let hit = if player_index == index {
                // TryPullItems leaves Magnet's own Player-layer hurtbox
                // enabled. The forward pull box can overlap it, routing the
                // caster back through the generic PlayerBody branch. That box
                // is where DetPhysics last put it: the published row, or the
                // entry pose on the entry pass.
                let row = &self.entities[target.magnet_entity];
                let extents = data::surface_extents(magnet.hurtbox_extents) * target.base.scale;
                let collider = OrientedBox {
                    center: Vec2::new(Fix::from_raw(row.x), Fix::from_raw(row.y)),
                    right: Vec2::new(Fix::from_raw(row.right_x), Fix::from_raw(row.right_y)),
                    up: Vec2::new(Fix::from_raw(row.up_x), Fix::from_raw(row.up_y)),
                    inverse_extents: Vec2::new(Fix::ONE / extents.x, Fix::ONE / extents.y),
                };
                crate::physics::contact::box_box(query, collider).is_some()
            } else {
                // A player in a form is found through that form's own shape.
                self.player_hit_by_box(player_index, query)
            };
            if !hit {
                continue;
            }
            // The shipped code accidentally measures closeness from the raw
            // prefab FirepointOffset rather than from the world firepoint.
            let mut strength = multiplier;
            if (target.base.position - raw_firepoint_offset).length_squared()
                < magnet.fast_pull_radius_squared
            {
                strength *= magnet.close_pull_multiplier;
            }
            if target.active == ActiveAbility::Rock {
                self.players[player_index].rock.body.force +=
                    (-magnet.pull_strength * strength) * direction;
            } else {
                let pull = if target.active == ActiveAbility::Throw {
                    magnet.macho_pull_strength
                } else {
                    magnet.player_pull_strength
                };
                self.players[player_index].base.external_velocity -= (pull * strength) * direction;
            }
        }
        for item in &mut self.thrown_items {
            let Some(entity) = item.entity else {
                continue;
            };
            if !item.active
                || item.magnet_holder.is_some()
                || self.entities[entity].flags & (E_ACTIVE | E_ENABLED) != E_ACTIVE | E_ENABLED
            {
                continue;
            }
            let radius = thrown_item_radius(data, *item);
            if crate::physics::contact::circle_box(
                Circle {
                    center: item.position,
                    radius,
                },
                query,
            )
            .is_none()
            {
                continue;
            }
            let mut strength = multiplier;
            if (item.position - raw_firepoint_offset).length_squared()
                < magnet.fast_pull_radius_squared
            {
                strength *= magnet.close_pull_multiplier;
            }
            item.body.force += (-magnet.pull_strength * strength) * direction;
        }
        for missile in &mut self.guided_missiles {
            if !missile.active || !missile.registered || missile.magnet_holder.is_some() {
                continue;
            }
            let collider = OrientedBox::from_basis(
                missile.position,
                Vec2::angle(missile.body.orientation),
                data.missile.spark_extents * missile.scale,
            );
            if crate::physics::contact::box_box(query, collider).is_none() {
                continue;
            }
            // The guided Missile carries an Item component and lives on layer
            // 10 (`item`), so MagnetGun routes it through the ordinary item
            // branch. ProjectilePullStr is reserved for layer 9 projectiles.
            let mut strength = multiplier;
            if (missile.position - raw_firepoint_offset).length_squared()
                < magnet.fast_pull_radius_squared
            {
                strength *= magnet.close_pull_multiplier;
            }
            missile.body.force += (-magnet.pull_strength * strength) * direction;
        }
        for arrow in &mut self.arrows {
            if !arrow.active || !arrow.registered || arrow.magnet_holder.is_some() {
                continue;
            }
            let contact = crate::physics::contact::circle_box(
                Circle {
                    center: arrow.position,
                    radius: data.arrow.radius * arrow.scale,
                },
                query,
            );
            if contact.is_none() {
                continue;
            }
            let mut strength = multiplier;
            if (arrow.position - raw_firepoint_offset).length_squared()
                < magnet.fast_pull_radius_squared
            {
                strength *= magnet.close_pull_multiplier;
            }
            arrow.force += (-magnet.projectile_pull_strength * strength) * direction;
        }
        for pickup_index in 0..self.ability_pickups.len() {
            let pickup = self.ability_pickups[pickup_index];
            if !pickup.active || self.blink_object_hidden(pickup.entity) {
                continue;
            }
            let collider = Circle {
                center: pickup.position + data.pickup.offset * pickup.scale,
                radius: data.pickup.radius * pickup.scale,
            };
            if crate::physics::contact::circle_box(collider, query).is_none() {
                continue;
            }
            let mut strength = multiplier;
            if (pickup.position - raw_firepoint_offset).length_squared()
                < magnet.fast_pull_radius_squared
            {
                strength *= magnet.close_pull_multiplier;
            }
            self.ability_pickups[pickup_index].body.force +=
                (-magnet.pull_strength * strength) * direction;
        }
        for shot_index in 0..self.portal_shots.len() {
            let shot = self.portal_shots[shot_index];
            if !shot.active || !shot.registered || self.blink_object_hidden(shot.entity) {
                continue;
            }
            if crate::physics::contact::circle_box(
                Circle {
                    center: shot.position,
                    radius: data.portal_gun.shot_radius,
                },
                query,
            )
            .is_none()
            {
                continue;
            }
            let mut strength = multiplier;
            if (shot.position - raw_firepoint_offset).length_squared()
                < magnet.fast_pull_radius_squared
            {
                strength *= magnet.close_pull_multiplier;
            }
            self.portal_shots[shot_index].body.force +=
                (-magnet.pull_strength * strength) * direction;
        }
        for marker_index in 0..self.revival_marker_pool.len() {
            let marker = self.revival_marker_pool[marker_index];
            if !marker.active || !marker.registered || self.blink_object_hidden(marker.entity) {
                continue;
            }
            let radius = marker
                .entity
                .map(|entity| Fix::from_raw(self.entities[entity].radius))
                .unwrap_or(data.revival.marker_radius);
            if crate::physics::contact::circle_box(
                Circle {
                    center: marker.position + data.revival.marker_offset,
                    radius,
                },
                query,
            )
            .is_none()
            {
                continue;
            }
            let mut strength = multiplier;
            if (marker.position - raw_firepoint_offset).length_squared()
                < magnet.fast_pull_radius_squared
            {
                strength *= magnet.close_pull_multiplier;
            }
            self.revival_marker_pool[marker_index].body.force +=
                (-magnet.pull_strength * strength) * direction;
        }
        for marker_index in 0..self.teleport_marker_pool.len() {
            let marker = self.teleport_marker_pool[marker_index];
            if !marker.active || !marker.registered || self.blink_object_hidden(marker.entity) {
                continue;
            }
            if crate::physics::contact::circle_box(
                Circle {
                    center: marker.position + data.teleport.marker_offset,
                    radius: data.teleport.marker_radius,
                },
                query,
            )
            .is_none()
            {
                continue;
            }
            let mut strength = multiplier;
            if (marker.position - raw_firepoint_offset).length_squared()
                < magnet.fast_pull_radius_squared
            {
                strength *= magnet.close_pull_multiplier;
            }
            self.teleport_marker_pool[marker_index].body.force +=
                (-magnet.pull_strength * strength) * direction;
        }
        for hole_index in 0..self.black_holes.len() {
            let hole = self.black_holes[hole_index];
            if !hole.active || self.blink_object_hidden(hole.entity) {
                continue;
            }
            if crate::physics::contact::circle_box(
                Circle {
                    center: hole.position,
                    radius: hole.radius,
                },
                query,
            )
            .is_none()
            {
                continue;
            }
            // BlackHole.AddForce divides by signed mass.
            if hole.mass != Fix::ZERO {
                self.black_holes[hole_index].velocity +=
                    (-magnet.black_hole_pull_strength * direction) / hole.mass;
            }
        }
        if changed {
            self.platforms_changed();
        }
    }

    fn magnet_firepoint(&self, index: usize, _data: &data::RolloutData) -> Vec2 {
        let slot = &self.players[index];
        let right = slot.magnet.body_right;
        let up = right.perp();
        // OnScaleChanged scales the serialized firepoint while extraOffset is
        // assigned in world units from the selected object.
        let offset = slot.magnet_firepoint_offsets[slot.active_slot] + slot.magnet.extra_offset;
        slot.base.position + up * offset.y + right * offset.x
    }

    fn magnet_wall_ray(
        &self,
        origin: Vec2,
        direction: Vec2,
        distance: Fix,
        excluded_platform: Option<usize>,
    ) -> Option<Fix> {
        let mut nearest = Fix::MAX;
        for (platform_index, platform) in self.platforms.iter().enumerate() {
            if excluded_platform == Some(platform_index) || !platform.active {
                continue;
            }
            if let Some(hit) = platform
                .collider
                .raycast(origin, direction)
                .filter(|hit| hit.near <= distance && hit.near < nearest)
            {
                nearest = hit.near;
            }
        }
        (nearest != Fix::MAX).then_some(nearest)
    }

    fn magnet_firepoint_before_item_walls(
        &self,
        index: usize,
        firepoint: Vec2,
        data: &data::RolloutData,
    ) -> Vec2 {
        let slot = &self.players[index];
        let direction = slot.magnet.aim.normalized_safe();
        let offset_x =
            slot.magnet_firepoint_offsets[slot.active_slot].x + slot.magnet.extra_offset.x;
        let root = firepoint - slot.magnet.body_right * offset_x;
        let side = data.magnet.raycast_offset * slot.base.scale;
        let distance = offset_x + Fix::from_int(1000);
        let excluded_platform = match slot.magnet.held {
            MagnetHeld::Boulder(boulder) => Some(self.macho_boulders[boulder].platform_index),
            _ => None,
        };
        let center =
            self.magnet_wall_ray(slot.base.position, direction, distance, excluded_platform);
        let upper = self.magnet_wall_ray(
            root + direction * side.x + direction.perp() * side.y,
            direction,
            distance,
            excluded_platform,
        );
        let lower = self.magnet_wall_ray(
            root + direction * side.x + direction.perp_cw() * side.y,
            direction,
            distance,
            excluded_platform,
        );
        let mut allowed = center.unwrap_or(offset_x);
        if let (Some(upper), Some(lower)) = (upper, lower) {
            allowed = upper.max(lower).min(center.unwrap_or(Fix::MAX));
        }
        if allowed < offset_x {
            root + direction * allowed
        } else {
            firepoint
        }
    }

    fn magnet_try_pickup_item(&mut self, index: usize, data: &data::RolloutData) {
        let firepoint = self.magnet_firepoint(index, data);
        let radius = data.magnet.pickup_radius * self.players[index].base.scale;
        let pickup_circle = Circle {
            center: firepoint,
            radius,
        };
        self.players[index].magnet.parry_registered = true;
        self.players[index].magnet.parry_circle = pickup_circle;

        let mut nearest = Fix::MAX;
        let mut selected = MagnetHeld::Nothing;
        let mut consider = |held: MagnetHeld, position: Vec2, overlaps: bool| {
            if !overlaps {
                return;
            }
            let distance = (position - firepoint).length_squared();
            if distance < nearest {
                nearest = distance;
                selected = held;
            }
        };

        // CircleCastAll visits each registered shape family in DetPhysics
        // order. Selection itself is strictly by centre distance, so a fixed
        // scan preserves all non-tie decisions without allocating a hit list.
        for player_index in 0..self.players.len() {
            if player_index == index || !self.playable(player_index) {
                continue;
            }
            let player = &self.players[player_index];
            if player.active == ActiveAbility::Rock {
                let circle = Circle {
                    center: player.base.position,
                    radius: player.rock.collider_radius,
                };
                consider(
                    MagnetHeld::Rock(player_index),
                    player.base.position,
                    crate::physics::contact::circle_circle(pickup_circle, circle).is_some(),
                );
            } else if player.active == ActiveAbility::None {
                consider(
                    MagnetHeld::Player(player_index),
                    player.base.position,
                    crate::physics::contact::circle_box(pickup_circle, player.base.collider)
                        .is_some(),
                );
            } else {
                // An ability form is hit through its own collider, and the
                // distance is measured to that collider's transform.
                let entity = Self::blink_player_entity(player);
                if !self.collides(entity) {
                    continue;
                }
                let row = self.entities[entity];
                let center = Vec2::new(Fix::from_raw(row.x), Fix::from_raw(row.y));
                let overlaps = if row.kind == 0 {
                    let circle = Circle { center, radius: Fix::from_raw(row.radius) };
                    crate::physics::contact::circle_circle(pickup_circle, circle).is_some()
                } else {
                    let right = Vec2::new(Fix::from_raw(row.right_x), Fix::from_raw(row.right_y));
                    let up = Vec2::new(Fix::from_raw(row.up_x), Fix::from_raw(row.up_y));
                    let form = OrientedBox {
                        center,
                        right,
                        up,
                        inverse_extents: Vec2::new(Fix::ONE / right.length(), Fix::ONE / up.length()),
                    };
                    crate::physics::contact::circle_box(pickup_circle, form).is_some()
                };
                consider(MagnetHeld::Player(player_index), center, overlaps);
            }
        }
        for (arrow_index, arrow) in self.arrows.iter().enumerate() {
            if !arrow.active || !arrow.registered {
                continue;
            }
            consider(
                MagnetHeld::Arrow(arrow_index),
                arrow.position,
                crate::physics::contact::circle_circle(
                    pickup_circle,
                    Circle {
                        center: arrow.position,
                        radius: data.arrow.radius * arrow.scale,
                    },
                )
                .is_some(),
            );
        }
        for (item_index, item) in self.thrown_items.iter().enumerate() {
            let Some(entity) = item.entity else { continue };
            if !item.active
                || self.entities[entity].flags & (E_ACTIVE | E_ENABLED) != E_ACTIVE | E_ENABLED
            {
                continue;
            }
            consider(
                MagnetHeld::ThrownItem(item_index),
                item.position,
                crate::physics::contact::circle_circle(
                    pickup_circle,
                    Circle {
                        center: item.position,
                        radius: thrown_item_radius(data, *item),
                    },
                )
                .is_some(),
            );
        }
        for (pickup_index, pickup) in self.ability_pickups.iter().enumerate() {
            if !pickup.active || self.blink_object_hidden(pickup.entity) {
                continue;
            }
            let center = pickup.position + data.pickup.offset * pickup.scale;
            consider(
                MagnetHeld::AbilityPickup(pickup_index),
                pickup.position,
                crate::physics::contact::circle_circle(
                    pickup_circle,
                    Circle {
                        center,
                        radius: data.pickup.radius * pickup.scale,
                    },
                )
                .is_some(),
            );
        }
        for (shot_index, shot) in self.portal_shots.iter().enumerate() {
            if !shot.active || !shot.registered || self.blink_object_hidden(shot.entity) {
                continue;
            }
            consider(
                MagnetHeld::PortalShot(shot_index),
                shot.position,
                crate::physics::contact::circle_circle(
                    pickup_circle,
                    Circle {
                        center: shot.position,
                        radius: data.portal_gun.shot_radius,
                    },
                )
                .is_some(),
            );
        }
        for (hole_index, hole) in self.black_holes.iter().enumerate() {
            if !hole.active || hole.mass <= Fix::ZERO || self.blink_object_hidden(hole.entity) {
                continue;
            }
            consider(
                MagnetHeld::BlackHole(hole_index),
                hole.position,
                crate::physics::contact::circle_circle(
                    pickup_circle,
                    Circle {
                        center: hole.position,
                        radius: hole.radius,
                    },
                )
                .is_some(),
            );
        }
        for (missile_index, missile) in self.guided_missiles.iter().enumerate() {
            if !missile.active || !missile.registered {
                continue;
            }
            let collider = OrientedBox::from_basis(
                missile.position,
                Vec2::angle(missile.body.orientation),
                data.missile.spark_extents * missile.scale,
            );
            consider(
                MagnetHeld::Missile(missile_index),
                missile.position,
                crate::physics::contact::circle_box(pickup_circle, collider).is_some(),
            );
        }
        for (boulder_index, boulder) in self.macho_boulders.iter().enumerate() {
            if !boulder.active || boulder.platform_index >= self.platforms.len() {
                continue;
            }
            let platform = &self.platforms[boulder.platform_index];
            let live = self.entities[self.platform_entities[boulder.platform_index]].flags
                & (E_ACTIVE | E_ENABLED)
                == E_ACTIVE | E_ENABLED;
            consider(
                MagnetHeld::Boulder(boulder_index),
                platform.surface.center,
                live && crate::physics::contact::circle_rounded(pickup_circle, platform.collider)
                    .is_some(),
            );
        }
        for (marker_index, marker) in self.revival_marker_pool.iter().enumerate() {
            if !marker.active || !marker.registered || self.blink_object_hidden(marker.entity) {
                continue;
            }
            let radius = marker
                .entity
                .map(|entity| Fix::from_raw(self.entities[entity].radius))
                .unwrap_or(data.revival.marker_radius);
            consider(
                MagnetHeld::RevivalMarker(marker_index),
                marker.position,
                crate::physics::contact::circle_circle(
                    pickup_circle,
                    Circle {
                        center: marker.position + data.revival.marker_offset,
                        radius,
                    },
                )
                .is_some(),
            );
        }
        for (marker_index, marker) in self.teleport_marker_pool.iter().enumerate() {
            if !marker.active || !marker.registered || self.blink_object_hidden(marker.entity) {
                continue;
            }
            consider(
                MagnetHeld::TeleportMarker(marker_index),
                marker.position,
                crate::physics::contact::circle_circle(
                    pickup_circle,
                    Circle {
                        center: marker.position + data.teleport.marker_offset,
                        radius: data.teleport.marker_radius,
                    },
                )
                .is_some(),
            );
        }

        if selected != MagnetHeld::Nothing {
            self.magnet_take_target(index, selected, data);
        }
    }

    fn magnet_take_target(&mut self, index: usize, held: MagnetHeld, data: &data::RolloutData) {
        // MagnetSteal/OnItemWasStolen pauses the previous holder. BlackHole's
        // shipped Hold method clears its own holder immediately, but the
        // currently locked gun still retains its private reference.
        for previous in 0..self.players.len() {
            if previous != index
                && self.players[previous].active == ActiveAbility::Magnet
                && self.players[previous].magnet.held == held
                && self.players[previous].magnet.phase != 5
            {
                self.players[previous].magnet.phase = 4;
                self.players[previous].magnet.held = MagnetHeld::Nothing;
            }
        }

        let (mut position, velocity, scale, boulder_recoil) = match held {
            MagnetHeld::ThrownItem(i) => {
                let item = self.thrown_items[i];
                (item.position, item.body.velocity, item.scale, false)
            }
            MagnetHeld::Missile(i) => {
                let missile = self.guided_missiles[i];
                (
                    missile.position,
                    missile.body.velocity,
                    missile.scale,
                    false,
                )
            }
            MagnetHeld::Arrow(i) => {
                let arrow = self.arrows[i];
                (arrow.position, arrow.velocity, Fix::ONE, false)
            }
            MagnetHeld::Player(i) => {
                let player = &self.players[i];
                (
                    player.base.position,
                    player.base.velocity + player.base.external_velocity,
                    player.base.scale,
                    false,
                )
            }
            MagnetHeld::Rock(i) => {
                let player = &self.players[i];
                (
                    player.base.position,
                    player.rock.body.velocity,
                    player.base.scale,
                    true,
                )
            }
            MagnetHeld::BlackHole(i) => {
                // dCircle.velocity: the DetPhysics body, never moved.
                (self.black_holes[i].position, Vec2::ZERO, Fix::ONE, false)
            }
            MagnetHeld::Boulder(i) => {
                let platform = self.macho_boulders[i].platform_index;
                (
                    self.platforms[platform].surface.center,
                    self.platform_dynamics[platform].body.velocity,
                    self.platform_dynamics[platform].scale,
                    true,
                )
            }
            MagnetHeld::AbilityPickup(i) => {
                let pickup = self.ability_pickups[i];
                (pickup.position, pickup.body.velocity, Fix::ONE, false)
            }
            MagnetHeld::PortalShot(i) => {
                let shot = self.portal_shots[i];
                (shot.position, shot.body.velocity, Fix::ONE, false)
            }
            MagnetHeld::RevivalMarker(i) => {
                let marker = self.revival_marker_pool[i];
                (marker.position, marker.body.velocity, marker.scale, false)
            }
            MagnetHeld::TeleportMarker(i) => {
                let marker = self.teleport_marker_pool[i];
                (marker.position, marker.body.velocity, Fix::ONE, false)
            }
            MagnetHeld::Nothing => return,
        };
        // MagnetGun exits an ability form with an ungrounded packet placed at
        // its CurrentFirePoint, but the form's own ExitAbility overwrites that
        // position with its body's. Only Drill and MeteorSmash pass it on;
        // CastSpell adds its ExitAbilityOffset.
        if let MagnetHeld::Player(victim) = held {
            match self.players[victim].active {
                ActiveAbility::Drill | ActiveAbility::Meteor => {
                    position = self.magnet_firepoint(index, data);
                }
                ActiveAbility::TimeStop => {
                    position += data.time_stop.exit_offset * self.players[victim].player_scale;
                }
                ActiveAbility::Throw => self.drop_macho_held_boulder(victim, data),
                _ => {}
            }
        }

        if self.players[index].magnet.phase == 1 {
            self.players[index].magnet.animation = 2;
            self.players[index].magnet.animation_ticks = 0;
        }
        let mut extra = Vec2::RIGHT * Fix::from_f32(1.5) * (scale.max(Fix::ONE) - Fix::ONE);
        if matches!(held, MagnetHeld::Rock(_)) {
            extra += data.magnet.player_rock_extra_offset;
        } else if matches!(held, MagnetHeld::Boulder(_)) {
            extra = data.magnet.boulder_extra_offset;
        }
        {
            let slot = &mut self.players[index];
            slot.magnet.phase = 3;
            slot.magnet.time_spent_pulling = Fix::ZERO;
            slot.magnet.held = held;
            slot.magnet.held_position = position;
            slot.magnet.extra_offset = extra;
            let divisor = if boulder_recoil {
                Fix::from_int(35)
            } else {
                data.magnet.player_mass
            };
            slot.base.external_velocity += velocity / divisor * Fix::from_int(35);
        }

        match held {
            MagnetHeld::ThrownItem(i) => {
                let item = &mut self.thrown_items[i];
                item.body.angular_velocity = data.magnet.locked_angular_velocity;
                item.magnet_holder = Some(index);
                item.magnet_hold_ticks = 3;
            }
            MagnetHeld::Missile(i) => {
                let missile = &mut self.guided_missiles[i];
                missile.body.angular_velocity = data.magnet.locked_angular_velocity;
                missile.magnet_holder = Some(index);
                missile.magnet_hold_ticks = 3;
            }
            MagnetHeld::Arrow(i) => {
                let arrow = &mut self.arrows[i];
                arrow.angular_velocity = data.magnet.locked_angular_velocity;
                arrow.magnet_holder = Some(index);
                arrow.magnet_hold_ticks = 3;
            }
            MagnetHeld::Player(i) => {
                if self.players[i].active != ActiveAbility::None {
                    self.exit_form_for_freeze(i, data);
                    self.players[i].base.position = position;
                    self.players[i].reported_position = position;
                    self.players[i].form_exit = Some((self.tick, position));
                }
                let slot = &mut self.players[i];
                // MagnetGun.cs:687 calls UnGround() with nullRotation.
                slot.base.unground_level(&self.platforms);
                slot.base.skip_next_gravity = true;
                slot.ragdoll = RagdollState {
                    active: true,
                    skip_physics: true,
                    hold_on_ground: false,
                    time: Fix::ZERO,
                    duration: data.magnet.small_ragdoll_duration,
                };
                slot.obs_state = STATE_RAGDOLL;
            }
            MagnetHeld::Rock(i) => {
                self.players[i].rock.body.angular_velocity = data.magnet.locked_angular_velocity;
            }
            MagnetHeld::Boulder(i) => {
                self.macho_boulders[i].held = true;
                let platform = self.macho_boulders[i].platform_index;
                self.platform_dynamics[platform].body.angular_velocity =
                    data.magnet.locked_angular_velocity;
                // MagnetGun.cs:747-753 calls UnGround() with its default
                // nullRotation, so the firepoint swings back to body.right
                // (1,0) for the rest of the pass.
                let slot = &mut self.players[index];
                if slot.base.grounded && slot.base.ground == Some(self.platforms[platform].id) {
                    slot.base.unground_level(&self.platforms);
                    slot.magnet.body_right = Vec2::RIGHT;
                }
            }
            MagnetHeld::AbilityPickup(i) => {
                self.ability_pickups[i].body.angular_velocity = data.magnet.locked_angular_velocity;
            }
            MagnetHeld::PortalShot(i) => {
                self.portal_shots[i].body.angular_velocity = data.magnet.locked_angular_velocity;
            }
            MagnetHeld::RevivalMarker(i) => {
                let marker = &mut self.revival_marker_pool[i];
                marker.body.angular_velocity = data.magnet.locked_angular_velocity;
                marker.magnet_holder = Some(index);
                marker.magnet_hold_ticks = 3;
            }
            MagnetHeld::TeleportMarker(i) => {
                let marker = &mut self.teleport_marker_pool[i];
                marker.body.angular_velocity = data.magnet.locked_angular_velocity;
                marker.magnet_holder = Some(index);
                marker.magnet_hold_ticks = 3;
            }
            MagnetHeld::BlackHole(_) | MagnetHeld::Nothing => {}
        }
    }

    /// MagnetGun.StaticUpdate runs after all ordinary UpdateSim callbacks and
    /// before DetPhysics. Every pickup attempt contributes one circle, even
    /// when its dynamic-object query finds nothing.
    fn magnet_parries_tick(&mut self, data: &data::RolloutData) {
        for first in 0..self.players.len() {
            if !self.players[first].magnet.parry_registered {
                continue;
            }
            for second in first + 1..self.players.len() {
                if !self.players[second].magnet.parry_registered
                    || crate::physics::contact::circle_circle(
                        self.players[first].magnet.parry_circle,
                        self.players[second].magnet.parry_circle,
                    )
                    .is_none()
                {
                    continue;
                }
                let direction = (self.players[first].base.position
                    - self.players[second].base.position)
                    .normalized_safe();
                self.parry_magnet(first, direction, data);
                self.parry_magnet(second, -direction, data);
            }
        }
    }

    fn parry_magnet(&mut self, index: usize, direction: Vec2, data: &data::RolloutData) {
        if self.players[index].active != ActiveAbility::Magnet
            || !matches!(self.players[index].magnet.phase, 1 | 2)
        {
            return;
        }
        let slot = &mut self.players[index];
        slot.magnet.phase = 4;
        slot.magnet.animation = 2;
        slot.magnet.animation_ticks = 0;
        slot.magnet.held = MagnetHeld::Nothing;
        slot.magnet.extra_offset = Vec2::ZERO;
        slot.base.external_velocity +=
            direction * data.magnet.parry_push_strength * Fix::from_int(35);
    }

    fn magnet_interpolate_held_position(
        &self,
        index: usize,
        firepoint: Vec2,
        raycast_walls: bool,
        data: &data::RolloutData,
    ) -> Vec2 {
        let body_position = self.players[index].base.position;
        let old = self.players[index].magnet.held_position;
        let old_direction = (old - body_position).normalized_safe();
        let target = firepoint - body_position;
        let mut distance = (old - body_position).length() * (Fix::ONE - data.magnet.held_lerp)
            + target.length() * data.magnet.held_lerp;
        let direction = slerp(
            old_direction,
            target.normalized_safe(),
            data.magnet.held_lerp,
        );
        let excluded_platform = match self.players[index].magnet.held {
            MagnetHeld::Boulder(boulder) => Some(self.macho_boulders[boulder].platform_index),
            _ => None,
        };
        if raycast_walls
            && let Some(wall) = self.magnet_wall_ray(
                body_position,
                direction,
                Fix::from_int(1000),
                excluded_platform,
            )
        {
            distance = distance.min(wall);
        }
        body_position + direction * distance
    }

    /// DetPhysics.MoveObjectOutOfWalls corrects with inverse masses 1 and 0
    /// whatever the body's own mass.
    fn magnet_circle_out_of_walls(&self, circle: Circle) -> Vec2 {
        self.platforms
            .iter()
            .find_map(|platform| {
                crate::physics::contact::circle_rounded(circle, platform.collider)
                    .map(|contact| positional_correction(contact, Fix::ONE, Fix::ZERO, true)[0])
            })
            .unwrap_or(Vec2::ZERO)
    }

    fn magnet_update_held_item(&mut self, index: usize, data: &data::RolloutData) {
        let held = self.players[index].magnet.held;
        let valid = match held {
            MagnetHeld::Nothing => false,
            MagnetHeld::ThrownItem(i) => self.thrown_items.get(i).is_some_and(|v| {
                v.active && v.magnet_holder == Some(index) && !self.blink_object_hidden(v.entity)
            }),
            MagnetHeld::Missile(i) => self.guided_missiles.get(i).is_some_and(|v| {
                v.active && v.magnet_holder == Some(index) && !self.blink_object_hidden(v.entity)
            }),
            MagnetHeld::Arrow(i) => self.arrows.get(i).is_some_and(|v| {
                v.active && v.magnet_holder == Some(index) && !self.blink_object_hidden(v.entity)
            }),
            MagnetHeld::Player(i) => i < self.players.len() && self.playable(i),
            MagnetHeld::Rock(i) => {
                i < self.players.len()
                    && self.playable(i)
                    && self.players[i].active == ActiveAbility::Rock
            }
            MagnetHeld::BlackHole(i) => self.black_holes.get(i).is_some_and(|v| {
                v.active && v.mass > Fix::ZERO && !self.blink_object_hidden(v.entity)
            }),
            MagnetHeld::Boulder(i) => self.macho_boulders.get(i).is_some_and(|v| {
                v.active
                    && v.platform_index < self.platforms.len()
                    && self.entities[self.platform_entities[v.platform_index]].flags & E_ACTIVE != 0
            }),
            MagnetHeld::AbilityPickup(i) => self
                .ability_pickups
                .get(i)
                .is_some_and(|v| v.active && !self.blink_object_hidden(v.entity)),
            MagnetHeld::PortalShot(i) => self
                .portal_shots
                .get(i)
                .is_some_and(|v| v.active && v.registered && !self.blink_object_hidden(v.entity)),
            MagnetHeld::RevivalMarker(i) => self.revival_marker_pool.get(i).is_some_and(|v| {
                v.active
                    && v.registered
                    && v.magnet_holder == Some(index)
                    && !self.blink_object_hidden(v.entity)
            }),
            MagnetHeld::TeleportMarker(i) => self.teleport_marker_pool.get(i).is_some_and(|v| {
                v.active
                    && v.registered
                    && v.magnet_holder == Some(index)
                    && !self.blink_object_hidden(v.entity)
            }),
        };
        if !valid {
            let state = &mut self.players[index].magnet;
            state.held = MagnetHeld::Nothing;
            state.phase = 4;
            state.extra_offset = Vec2::ZERO;
            return;
        }

        let object_position = match held {
            MagnetHeld::ThrownItem(i) => self.thrown_items[i].position,
            MagnetHeld::Missile(i) => self.guided_missiles[i].position,
            MagnetHeld::Arrow(i) => self.arrows[i].position,
            MagnetHeld::Player(i) | MagnetHeld::Rock(i) => self.players[i].base.position,
            MagnetHeld::BlackHole(i) => self.black_holes[i].position,
            MagnetHeld::Boulder(i) => {
                self.platforms[self.macho_boulders[i].platform_index]
                    .surface
                    .center
            }
            MagnetHeld::AbilityPickup(i) => self.ability_pickups[i].position,
            MagnetHeld::PortalShot(i) => self.portal_shots[i].position,
            MagnetHeld::RevivalMarker(i) => self.revival_marker_pool[i].position,
            MagnetHeld::TeleportMarker(i) => self.teleport_marker_pool[i].position,
            MagnetHeld::Nothing => unreachable!(),
        };
        let mut firepoint = self.magnet_firepoint(index, data);
        if !matches!(
            held,
            MagnetHeld::BlackHole(_) | MagnetHeld::RevivalMarker(_) | MagnetHeld::TeleportMarker(_)
        ) {
            firepoint = self.magnet_firepoint_before_item_walls(index, firepoint, data);
        }
        if (firepoint - object_position).length_squared() > data.magnet.max_lock_distance_squared {
            let state = &mut self.players[index].magnet;
            state.held = MagnetHeld::Nothing;
            state.phase = 2;
            state.extra_offset = Vec2::ZERO;
            return;
        }

        let position = self.magnet_interpolate_held_position(
            index,
            firepoint,
            !matches!(
                held,
                MagnetHeld::BlackHole(_)
                    | MagnetHeld::RevivalMarker(_)
                    | MagnetHeld::TeleportMarker(_)
            ),
            data,
        );
        self.players[index].magnet.held_position = position;
        match held {
            MagnetHeld::ThrownItem(i) => {
                let velocity = self.thrown_items[i].body.velocity;
                self.players[index].base.external_velocity += velocity / Fix::from_int(10);
                let radius = thrown_item_radius(data, self.thrown_items[i]);
                let correction = self.magnet_circle_out_of_walls(Circle {
                    center: position,
                    radius,
                });
                let item = &mut self.thrown_items[i];
                item.position = position + correction;
                item.body.velocity = Vec2::ZERO;
                item.magnet_holder = Some(index);
                item.magnet_hold_ticks = 2;
            }
            MagnetHeld::Missile(i) => {
                let velocity = self.guided_missiles[i].body.velocity;
                self.players[index].base.external_velocity += velocity / Fix::from_int(10);
                let missile = &mut self.guided_missiles[i];
                missile.position = position;
                missile.body.velocity = Vec2::ZERO;
                missile.magnet_holder = Some(index);
                missile.magnet_hold_ticks = 2;
                let shape = RoundedRect {
                    inner: OrientedBox::from_basis(
                        missile.position,
                        Vec2::angle(missile.body.orientation),
                        data.missile.spark_extents * missile.scale,
                    ),
                    radius: Fix::ZERO,
                };
                if let Some(contact) = self.platforms.iter().find_map(|platform| {
                    crate::physics::contact::rounded_rounded(shape, platform.collider)
                }) {
                    missile.position +=
                        positional_correction(contact, missile.body.inverse_mass, Fix::ZERO, true)
                            [0];
                }
            }
            MagnetHeld::Arrow(i) => {
                let velocity = self.arrows[i].velocity;
                let scale = self.arrows[i].scale;
                self.players[index].base.external_velocity += velocity / Fix::from_int(10);
                let correction = self.magnet_circle_out_of_walls(Circle {
                    center: position,
                    radius: data.arrow.radius * scale,
                });
                let arrow = &mut self.arrows[i];
                arrow.position = position + correction;
                arrow.velocity = Vec2::ZERO;
                arrow.magnet_holder = Some(index);
                arrow.magnet_hold_ticks = 2;
            }
            MagnetHeld::Player(i) => {
                let slot = &mut self.players[i];
                slot.base.position = position;
                slot.base.velocity = Vec2::ZERO;
                slot.base.skip_next_gravity = true;
                slot.ragdoll = RagdollState {
                    active: true,
                    skip_physics: true,
                    hold_on_ground: false,
                    time: Fix::ZERO,
                    duration: data.magnet.small_ragdoll_duration,
                };
                slot.obs_state = STATE_RAGDOLL;
                // MagnetGun.LateUpdateSim pins whichever rope endpoint owns
                // the held PlayerBody after forcing it off its ground.
                if let Some(rope_index) = slot.rope
                    && rope_index < self.ropes.len()
                    && self.ropes[rope_index].physics.enabled
                {
                    let endpoint = if slot.rope_top {
                        0
                    } else {
                        self.ropes[rope_index].physics.count - 1
                    };
                    self.ropes[rope_index].physics.segment[endpoint] = position;
                }
            }
            MagnetHeld::Rock(i) => {
                let velocity = self.players[i].rock.body.velocity;
                self.players[index].base.external_velocity += velocity / Fix::from_int(10);
                let holder_dt = if self.player_time_scale < Fix::from_f32(0.01)
                    && !self.time_stop_protected[index]
                {
                    Fix::ZERO
                } else {
                    DT
                };
                // The item branch compensates BounceBall.LateUpdateSim's
                // activation clock so a held player Rock does not expire.
                self.players[i].rock.time -= holder_dt;
                let correction = self.magnet_circle_out_of_walls(Circle {
                    center: position,
                    radius: self.players[i].rock.collider_radius,
                });
                let rock = &mut self.players[i];
                rock.base.position = position + correction;
                rock.rock.body.velocity = Vec2::ZERO;
                rock.base.velocity = Vec2::ZERO;
            }
            MagnetHeld::BlackHole(i) => {
                self.black_holes[i].position = position;
                if let Some(entity) = self.black_holes[i].entity {
                    self.entities[entity].x = position.x.raw();
                    self.entities[entity].y = position.y.raw();
                }
            }
            MagnetHeld::Boulder(i) => {
                let platform = self.macho_boulders[i].platform_index;
                let velocity = self.platform_dynamics[platform].body.velocity;
                self.players[index].base.external_velocity += velocity / Fix::from_int(10);
                // DetPhysics.MoveObjectOutOfWalls: the first overlapping
                // rounded rect in collider order pushes the boulder fully out.
                let mut shape = self.platforms[platform].collider;
                shape.inner.center = position;
                let position = position
                    + self
                        .platforms
                        .iter()
                        .enumerate()
                        .filter(|&(other, wall)| other != platform && wall.active)
                        .find_map(|(_, wall)| {
                            crate::physics::contact::rounded_rounded(shape, wall.collider)
                        })
                        .map_or(Vec2::ZERO, |contact| {
                            positional_correction(contact, Fix::ONE, Fix::ZERO, true)[0]
                        });
                self.platforms[platform].surface.center = position;
                self.platforms[platform].collider.inner.center = position;
                self.platform_dynamics[platform].composite_position = position;
                self.platform_dynamics[platform].home_position = position;
                self.platform_dynamics[platform].body.velocity = Vec2::ZERO;
                self.macho_boulders[i].held = true;
                self.platforms_changed();
            }
            MagnetHeld::AbilityPickup(i) => {
                let velocity = self.ability_pickups[i].body.velocity;
                let scale = self.ability_pickups[i].scale;
                self.players[index].base.external_velocity += velocity / Fix::from_int(10);
                let correction = self.magnet_circle_out_of_walls(Circle {
                    center: position + data.pickup.offset * scale,
                    radius: data.pickup.radius * scale,
                });
                let pickup = &mut self.ability_pickups[i];
                pickup.position = position + correction;
                pickup.body.velocity = Vec2::ZERO;
            }
            MagnetHeld::PortalShot(i) => {
                let velocity = self.portal_shots[i].body.velocity;
                self.players[index].base.external_velocity += velocity / Fix::from_int(10);
                let correction = self.magnet_circle_out_of_walls(Circle {
                    center: position,
                    radius: data.portal_gun.shot_radius,
                });
                let shot = &mut self.portal_shots[i];
                shot.position = position + correction;
                shot.body.velocity = Vec2::ZERO;
            }
            MagnetHeld::RevivalMarker(i) => {
                let velocity = self.revival_marker_pool[i].body.velocity;
                self.players[index].base.external_velocity += velocity / Fix::from_int(10);
                let marker = &mut self.revival_marker_pool[i];
                marker.position = position;
                marker.body.velocity = Vec2::ZERO;
                marker.magnet_holder = Some(index);
                marker.magnet_hold_ticks = 2;
            }
            MagnetHeld::TeleportMarker(i) => {
                let velocity = self.teleport_marker_pool[i].body.velocity;
                self.players[index].base.external_velocity += velocity / Fix::from_int(10);
                let marker = &mut self.teleport_marker_pool[i];
                marker.position = position;
                marker.body.velocity = Vec2::ZERO;
                marker.magnet_holder = Some(index);
                marker.magnet_hold_ticks = 2;
            }
            MagnetHeld::Nothing => {}
        }
    }

    fn magnet_release_handle(&mut self, index: usize, held: MagnetHeld) {
        match held {
            MagnetHeld::ThrownItem(i) => {
                if let Some(item) = self.thrown_items.get_mut(i)
                    && item.magnet_holder == Some(index)
                {
                    item.magnet_holder = None;
                    item.magnet_hold_ticks = -1;
                }
            }
            MagnetHeld::Missile(i) => {
                if let Some(missile) = self.guided_missiles.get_mut(i)
                    && missile.magnet_holder == Some(index)
                {
                    missile.magnet_holder = None;
                    missile.magnet_hold_ticks = -1;
                }
            }
            MagnetHeld::Arrow(i) => {
                if let Some(arrow) = self.arrows.get_mut(i)
                    && arrow.magnet_holder == Some(index)
                {
                    arrow.magnet_holder = None;
                    arrow.magnet_hold_ticks = -1;
                }
            }
            MagnetHeld::Boulder(i) => {
                if let Some(boulder) = self.macho_boulders.get_mut(i) {
                    boulder.held = false;
                }
            }
            MagnetHeld::RevivalMarker(i) => {
                if let Some(marker) = self.revival_marker_pool.get_mut(i)
                    && marker.magnet_holder == Some(index)
                {
                    marker.magnet_holder = None;
                    marker.magnet_hold_ticks = -1;
                }
            }
            MagnetHeld::TeleportMarker(i) => {
                if let Some(marker) = self.teleport_marker_pool.get_mut(i)
                    && marker.magnet_holder == Some(index)
                {
                    marker.magnet_holder = None;
                    marker.magnet_hold_ticks = -1;
                }
            }
            MagnetHeld::Nothing
            | MagnetHeld::Player(_)
            | MagnetHeld::Rock(_)
            | MagnetHeld::BlackHole(_)
            | MagnetHeld::AbilityPickup(_)
            | MagnetHeld::PortalShot(_) => {}
        }
    }

    fn magnet_fire_held_item(&mut self, index: usize, direction: Vec2, data: &data::RolloutData) {
        let held = core::mem::take(&mut self.players[index].magnet.held);
        self.players[index].magnet.extra_offset = Vec2::ZERO;
        match held {
            MagnetHeld::Arrow(i) => {
                if let Some(arrow) = self.arrows.get_mut(i) {
                    arrow.force += direction * data.magnet.fire_force * Fix::from_int(2);
                }
            }
            MagnetHeld::Missile(i) => {
                if let Some(missile) = self.guided_missiles.get_mut(i) {
                    missile.up = direction;
                    missile.body.velocity = direction * data.magnet.fire_missile_force;
                    missile.body.orientation = direction.perp_cw().normalized_angle();
                }
            }
            MagnetHeld::ThrownItem(i) => {
                if let Some(item) = self.thrown_items.get_mut(i) {
                    if item.ability == ABILITY_MINE {
                        item.body.velocity = direction * data.magnet.fire_force_mines;
                    }
                    item.body.force += direction * data.magnet.fire_force;
                }
            }
            MagnetHeld::Player(i) => {
                let rope = self.players.get(i).and_then(|slot| slot.rope);
                let rope_top = self.players.get(i).is_some_and(|slot| slot.rope_top);
                let mut speed = direction * data.magnet.fire_ragdoll_force;
                // ApplyRagDoll turns the body to face the throw before it
                // slows the horizontal part (SlimeController.cs:1026-1034).
                let right = speed.normalized_safe();
                speed.x /= Fix::from_f32(1.5);
                if let Some(slot) = self.players.get_mut(i) {
                    slot.base.velocity = speed;
                    if right != Vec2::ZERO {
                        slot.base.up = right.perp();
                        slot.base.rotation = right.normalized_angle();
                    }
                    // ApplyRagDoll leaves the skipNextUpdate this pass's hold
                    // already set (MagnetGun.cs:1127-1128).
                    slot.ragdoll = RagdollState {
                        active: true,
                        skip_physics: slot.ragdoll.skip_physics,
                        hold_on_ground: false,
                        time: Fix::ZERO,
                        duration: data.magnet.fire_ragdoll_duration,
                    };
                    slot.obs_state = STATE_RAGDOLL;
                    slot.base.collision_rays(terrain!(self));
                }
                if speed.y > Fix::ZERO
                    && let Some(rope_index) = rope
                    && let Some(rope) = self.ropes.get_mut(rope_index)
                {
                    if rope_top {
                        rope.time_air_start = Fix::from_f64(0.1);
                    } else {
                        rope.time_air_end = Fix::from_f64(0.1);
                    }
                }
            }
            MagnetHeld::Rock(i) => {
                if let Some(slot) = self.players.get_mut(i) {
                    slot.rock.body.force += direction * data.magnet.fire_rock_force;
                }
            }
            MagnetHeld::BlackHole(i) => {
                if let Some(hole) = self.black_holes.get_mut(i) {
                    hole.velocity += direction * data.magnet.fire_black_hole_force;
                }
            }
            MagnetHeld::Boulder(i) => {
                if let Some(boulder) = self.macho_boulders.get_mut(i) {
                    boulder.held = false;
                    let platform = boulder.platform_index;
                    if let Some(dynamics) = self.platform_dynamics.get_mut(platform) {
                        dynamics.body.force += direction * data.magnet.fire_boulder_force;
                    }
                }
            }
            MagnetHeld::AbilityPickup(i) => {
                if let Some(pickup) = self.ability_pickups.get_mut(i) {
                    pickup.body.force += direction * data.magnet.fire_force;
                }
            }
            MagnetHeld::PortalShot(i) => {
                if let Some(shot) = self.portal_shots.get_mut(i) {
                    shot.body.force += direction * data.magnet.fire_force;
                }
            }
            MagnetHeld::RevivalMarker(i) => {
                if let Some(marker) = self.revival_marker_pool.get_mut(i) {
                    marker.body.force += direction * data.magnet.fire_force * marker.scale;
                }
            }
            MagnetHeld::TeleportMarker(i) => {
                if let Some(marker) = self.teleport_marker_pool.get_mut(i) {
                    marker.body.force += direction * data.magnet.fire_force;
                }
            }
            MagnetHeld::Nothing => {}
        }
    }

    fn drop_magnet_held_item(&mut self, index: usize) {
        let held = core::mem::take(&mut self.players[index].magnet.held);
        self.players[index].magnet.extra_offset = Vec2::ZERO;
        self.magnet_release_handle(index, held);
    }

    fn fire_magnet(&mut self, index: usize, data: &data::RolloutData) {
        // MagnetGun.Fire faces the body along the aim as stored and only
        // renormalizes it for the shot and the knockback.
        let facing = self.players[index].magnet.aim;
        let aim = facing.normalized_safe();
        if self.players[index].magnet.phase == 3 {
            self.magnet_fire_held_item(index, aim, data);
        }
        let normal = self.players[index]
            .base
            .ground
            .and_then(|id| self.platforms.iter().find(|p| p.id == id))
            .map(|platform| platform.surface.normal(self.players[index].base.position));
        let grounded = self.players[index].base.grounded;
        let slot = &mut self.players[index];
        slot.magnet.has_fired = true;
        slot.gun_gravity[slot.active_slot] = Fix::ONE;
        slot.magnet.phase = 5;
        slot.magnet.animation = 3;
        slot.magnet.animation_ticks = 0;
        slot.magnet.body_right = facing;
        slot.base.up = facing.perp();
        slot.base.rotation = facing.normalized_angle();
        if grounded {
            slot.base.velocity = -(normal.unwrap_or(slot.base.up) * data.magnet.knockback);
            slot.base.force_unground(&self.platforms);
        } else {
            slot.base.velocity = -(aim * data.magnet.knockback);
        }
    }

    fn exit_magnet(&mut self, index: usize, landed: bool, data: &data::RolloutData) {
        self.drop_magnet_held_item(index);
        let terrain = terrain!(self);
        let landed_surface = landed.then(|| {
            let ground = self.players[index]
                .base
                .ground
                .expect("landed Magnet has a ground");
            terrain
                .platforms
                .iter()
                .find(|platform| platform.id == ground)
                .expect("landed Magnet ground remains registered")
        });
        let ordinary_radius = self.players[index].exit_slime_radius();
        let landed_local = landed_surface.map(|platform| {
            platform
                .surface
                .local_position(self.players[index].base.position, ordinary_radius)
                .expect("Magnet landing position lies on its platform")
        });
        let slot = &mut self.players[index];
        // MagnetGun.ExitAbility: `isFacingRight = inputVector.x >= 0`.
        slot.facing_right = slot.magnet.aim.x >= Fix::ZERO;
        slot.base.rotation = Fix::ZERO;
        slot.base.up = Vec2::UP;
        if !landed {
            slot.base.force_unground(terrain.platforms);
        }
        slot.active = ActiveAbility::None;
        slot.exit_to_fall();
        slot.reported_position = slot.base.position;
        slot.reported_tick = self.tick;
        slot.restore_slime_radius();
        if !landed {
            slot.base.ground = None;
            slot.base.collision_rays(terrain);
        } else if let (Some(platform), Some(local)) = (landed_surface, landed_local) {
            slot.base.local = local;
            slot.base.velocity = Vec2::ZERO;
            slot.base.align(platform);
        }
        slot.base.constants = data.player.constants.clone();
        slot.set_ordinary_body_scale(slot.player_scale);
    }

    fn fire_duplicator(&mut self, index: usize, data: &data::RolloutData) {
        let gun = &data.duplicator;
        let (aim, grounded, normal) = {
            let slot = &self.players[index];
            (
                slot.gun.aim.normalized_safe(),
                slot.base.grounded,
                slot.base
                    .ground
                    .and_then(|id| self.platforms.iter().find(|p| p.id == id))
                    .map(|p| p.surface.normal(slot.base.position)),
            )
        };
        {
            let slot = &mut self.players[index];
            slot.gun.has_fired = true;
            slot.gun_gravity[slot.active_slot] = Fix::ONE;
            slot.gun.fire_ticks = gun.fire_ticks;
            // GunTransform.Fire assigns up from inputVector before normalizing
            // it again for the shot and knockback.
            slot.base.up = slot.gun.aim.perp();
            slot.base.rotation = slot.gun.aim.normalized_angle();
        }
        let firepoint = {
            let slot = &self.players[index];
            let offset = gun.firepoint_offset * slot.base.scale;
            slot.base.position + slot.base.up * offset.y + aim * offset.x
        };
        self.shoot_duplicator_ray(firepoint, aim, index, data, false);

        let slot = &mut self.players[index];
        if grounded {
            slot.base.velocity = -(normal.unwrap_or(slot.base.up) * gun.knockback);
            slot.base.force_unground(&self.platforms);
            slot.base.rotation = Fix::ZERO;
            slot.base.up = Vec2::UP;
        } else {
            slot.base.velocity = -(aim * gun.knockback);
        }
    }

    fn exit_duplicator_landing(&mut self, index: usize) {
        let platform_index = self.players[index]
            .base
            .ground
            .and_then(|id| self.platforms.iter().position(|platform| platform.id == id))
            .expect("grounded Duplicator has a platform");
        let platform = &self.platforms[platform_index];
        let form_radius = self.players[index].base.radius;
        let position = platform
            .surface
            .position(self.players[index].base.local, form_radius);
        let ordinary_radius = self.players[index].exit_slime_radius();
        let local = platform
            .surface
            .local_position(position, ordinary_radius)
            .expect("Duplicator exit lies on the platform");
        let slot = &mut self.players[index];
        slot.facing_right = slot.gun.aim.x >= Fix::ZERO;
        slot.active = ActiveAbility::None;
        slot.exit_to_fall();
        slot.base.local = local;
        slot.base.position = position;
        slot.base.velocity = Vec2::ZERO;
        slot.restore_slime_radius();
        slot.base.align(platform);
        slot.reported_position = position;
        slot.reported_tick = self.tick;
        slot.set_ordinary_body_scale(slot.player_scale);
    }

    fn shoot_duplicator_ray(
        &mut self,
        origin: Vec2,
        direction: Vec2,
        caster: usize,
        data: &data::RolloutData,
        already_hit_water: bool,
    ) {
        let gun = &data.duplicator;
        let mask = if already_hit_water {
            gun.collision_mask_no_water
        } else {
            gun.collision_mask
        };
        let max_distance = Fix::from_int(100);
        let excluded = (!already_hit_water).then_some(self.players[caster].duplicator_entity);

        // PointCheckAllRoundedRects precedes the ray and keeps the last
        // overlapping rounded rectangle in DetPhysics registration order.
        let mut selected = None;
        for (entity, row) in self.entities.iter().enumerate() {
            if row.kind != 2 || row.flags & E_ACTIVE == 0 || excluded == Some(entity) {
                continue;
            }
            if Self::entity_rounded_rect(*row).is_some_and(|shape| shape.overlaps(origin)) {
                selected = Some(DuplicatorRayHit {
                    entity,
                    distance: Fix::from_f32(0.001),
                    position: origin,
                });
            }
        }

        if selected.is_none() {
            let side = direction.perp() * gun.triple_raycast_radius;
            let center =
                self.duplicator_raycast_one(origin, direction, max_distance, mask, excluded, data);
            let positive = self.duplicator_raycast_one(
                origin + side,
                direction,
                max_distance,
                mask,
                excluded,
                data,
            );
            let negative = self.duplicator_raycast_one(
                origin - side,
                direction,
                max_distance,
                mask,
                excluded,
                data,
            );
            let center_distance = center.map_or(Fix::MAX, |hit| hit.distance);
            let positive_distance = positive.map_or(Fix::MAX, |hit| hit.distance);
            let negative_distance = negative.map_or(Fix::MAX, |hit| hit.distance);
            selected = if center_distance < positive_distance && center_distance < negative_distance
            {
                center
            } else if positive_distance < center_distance && positive_distance < negative_distance {
                positive
            } else if negative_distance < positive_distance && negative_distance < center_distance {
                negative
            } else {
                center
            };
        }

        // ShootDuplicator overwrites an initial below-water hit with the
        // casting gun's own Player body, then duplicates it upward. This is
        // independent of whether the triple ray found another collider.
        if !already_hit_water && origin.y <= Fix::from_f32(-11.3) {
            let position = self.players[caster].base.position;
            self.duplicate_player_target(caster, position, Vec2::UP, data);
            return;
        }

        let Some(hit) = selected else {
            return;
        };
        if hit.entity == usize::MAX {
            self.shoot_duplicator_ray(
                hit.position,
                Vec2::new(direction.x, -direction.y),
                caster,
                data,
                true,
            );
            return;
        }
        if let Some(victim) = self.players.iter().position(|slot| {
            self.playable_slot(slot) && Self::blink_player_entity(slot) == hit.entity
        }) {
            self.duplicate_player_target(victim, hit.position, direction, data);
            return;
        }
        if let Some(platform_index) = self
            .platform_entities
            .iter()
            .position(|&entity| entity == hit.entity)
        {
            self.begin_duplicate_platform(platform_index, hit.position, direction, caster, data);
            return;
        }
        if let Some(arrow_index) = self
            .arrows
            .iter()
            .position(|arrow| arrow.active && arrow.registered && arrow.entity == Some(hit.entity))
        {
            self.duplicate_arrow(arrow_index, direction, data);
            return;
        }
        if let Some(item_index) = self
            .thrown_items
            .iter()
            .position(|item| item.active && item.entity == Some(hit.entity))
        {
            self.duplicate_thrown_item(item_index, direction, data);
            return;
        }
        if let Some(missile_index) = self
            .guided_missiles
            .iter()
            .position(|missile| missile.active && missile.entity == Some(hit.entity))
        {
            self.duplicate_guided_missile(missile_index, direction, data);
            return;
        }
        if let Some(cloud_index) = self
            .smoke_clouds
            .iter()
            .position(|cloud| cloud.active && cloud.entity == Some(hit.entity))
        {
            self.duplicate_smoke_cloud(cloud_index, data);
            return;
        }
        if let Some(pickup_index) = self
            .ability_pickups
            .iter()
            .position(|pickup| pickup.active && pickup.entity == Some(hit.entity))
        {
            self.duplicate_ability_pickup(pickup_index, direction, data);
            return;
        }
        if let Some(hole_index) = self
            .black_holes
            .iter()
            .position(|hole| hole.active && hole.entity == Some(hit.entity))
        {
            self.duplicate_black_hole(hole_index, direction, data);
            return;
        }
        if let Some(rock_index) = self
            .duplicated_rocks
            .iter()
            .position(|rock| rock.active && rock.entity == Some(hit.entity))
        {
            self.duplicate_lethal_rock(rock_index, direction, data);
            return;
        }
        if let Some(spike_index) = self.spike_attacks.iter().position(|spike| {
            spike.active && !spike.macho_carried && spike.entity == Some(hit.entity)
        }) {
            self.duplicate_attached_spike(spike_index, direction, data);
            return;
        }
        if let Some(engine_index) = self.engines.iter().position(|engine| {
            engine.active && !engine.macho_carried && engine.entity == Some(hit.entity)
        }) {
            self.duplicate_attached_engine(engine_index, direction, caster, data);
            return;
        }
        if let Some(node_index) = self
            .tesla_nodes
            .iter()
            .position(|node| node.active && !node.macho_carried && node.entity == Some(hit.entity))
        {
            self.duplicate_attached_tesla(node_index, direction, caster, data);
            return;
        }
        if self.entities[hit.entity].layer == 26
            && let Some(orb) = self
                .beam_orbs
                .iter_mut()
                .find(|orb| orb.active && orb.entity == Some(hit.entity))
        {
            orb.orb_type = 4;
        }
    }

    fn entity_rounded_rect(row: CEntity) -> Option<RoundedRect> {
        if row.kind != 2 {
            return None;
        }
        let right = Vec2::new(Fix::from_raw(row.right_x), Fix::from_raw(row.right_y));
        let up = Vec2::new(Fix::from_raw(row.up_x), Fix::from_raw(row.up_y));
        if right == Vec2::ZERO || up == Vec2::ZERO {
            return None;
        }
        Some(RoundedRect {
            inner: OrientedBox {
                center: Vec2::new(Fix::from_raw(row.x), Fix::from_raw(row.y)),
                right,
                up,
                inverse_extents: Vec2::new(Fix::ONE / right.length(), Fix::ONE / up.length()),
            },
            radius: Fix::from_raw(row.radius),
        })
    }

    fn duplicator_raycast_one(
        &self,
        origin: Vec2,
        direction: Vec2,
        max_distance: Fix,
        mask: u32,
        excluded: Option<usize>,
        data: &data::RolloutData,
    ) -> Option<DuplicatorRayHit> {
        let mut best = None;
        let mut nearest = Fix::MAX;
        // RaycastToClosest visits rounded rectangles, circles, then boxes.
        for kind in [2u32, 0, 1] {
            for (entity, row) in self.entities.iter().copied().enumerate() {
                if row.kind != kind
                    || row.flags & E_ACTIVE == 0
                    || excluded == Some(entity)
                    || mask & (1 << row.layer) == 0
                    || self.left_form_row(entity)
                {
                    continue;
                }
                let center = Vec2::new(Fix::from_raw(row.x), Fix::from_raw(row.y));
                let distance = match kind {
                    0 => Circle {
                        center,
                        radius: Fix::from_raw(row.radius),
                    }
                    .raycast(origin, direction)
                    .map(|hit| hit.near),
                    1 => {
                        let right =
                            Vec2::new(Fix::from_raw(row.right_x), Fix::from_raw(row.right_y));
                        let up = Vec2::new(Fix::from_raw(row.up_x), Fix::from_raw(row.up_y));
                        (right != Vec2::ZERO && up != Vec2::ZERO)
                            .then(|| OrientedBox {
                                center,
                                right,
                                up,
                                inverse_extents: Vec2::new(
                                    Fix::ONE / right.length(),
                                    Fix::ONE / up.length(),
                                ),
                            })
                            .and_then(|shape| shape.raycast(origin, direction))
                            .map(|hit| hit.near)
                    }
                    _ => Self::entity_rounded_rect(row)
                        .and_then(|shape| shape.raycast(origin, direction))
                        .map(|hit| hit.near),
                };
                if let Some(distance) = distance
                    && distance < nearest
                    && distance <= max_distance
                {
                    nearest = distance;
                    best = Some(DuplicatorRayHit {
                        entity,
                        distance,
                        position: origin + direction * distance,
                    });
                }
            }
            // The scene water is a DPhysicsBox instantiated before player
            // prefabs, so it precedes the other box rows in this collection.
            if kind == 0
                && mask & (1 << LAYER_WATER) != 0
                && let Some((water_position, water_extents, _)) = data.maps[self.map].water
            {
                let water = OrientedBox::from_basis(
                    water_position,
                    Vec2::RIGHT,
                    data::surface_extents(water_extents),
                );
                if let Some(hit) = water.raycast(origin, direction)
                    && hit.near < nearest
                    && hit.near <= max_distance
                {
                    nearest = hit.near;
                    best = Some(DuplicatorRayHit {
                        entity: usize::MAX,
                        distance: hit.near,
                        position: origin + direction * hit.near,
                    });
                }
            }
        }
        best
    }

    fn fan_out(
        clone_count: u32,
        direction: Vec2,
        position: Vec2,
        offset: Fix,
        angle: Fix,
        index: u32,
    ) -> Vec2 {
        let turn = match (clone_count, index) {
            (2, 0) | (3, 1) | (4, 0) => angle,
            (2, 1) | (3, 2) | (4, 1) => -angle,
            (4, 2) => angle * Fix::from_int(3),
            (4, 3) => -angle * Fix::from_int(3),
            _ => Fix::ZERO,
        };
        position + direction.complex_mul(Vec2::angle(turn)) * offset
    }

    fn duplicate_arrow(&mut self, source_index: usize, direction: Vec2, data: &data::RolloutData) {
        let source = self.arrows[source_index];
        let speed = source.velocity.length() + Fix::from_int(10);
        for clone_index in 0..4 {
            let position = Self::fan_out(
                4,
                direction,
                source.position,
                Fix::from_int(7) * source.scale,
                Fix::from_f32(0.32),
                clone_index,
            );
            let velocity = (position - source.position).normalized_safe() * speed;
            let hierarchy_base = self.next_spawn_hierarchy;
            self.next_spawn_hierarchy += data.arrow.updatable_count;
            let free = self.arrows.iter().position(|arrow| !arrow.active);
            self.release_arrow_row(free);
            let id = self.next_id();
            let clone = Arrow {
                active: true,
                born_tick: self.tick,
                hierarchy_base,
                registered: false,
                id,
                // Projectile.playerOwnerId is private and not serialized;
                // Instantiate therefore creates an environmental copy.
                owner: 0,
                entity: None,
                position,
                scale: source.scale,
                mass_scale: Fix::ONE,
                inverse_mass: data.arrow.body.inverse_mass,
                inverse_inertia: data.arrow.body.inverse_inertia,
                velocity,
                force: Vec2::ZERO,
                angular_velocity: source.angular_velocity,
                updater_tick: u32::MAX,
                rotation: source.rotation,
                time_passed: source.time_passed,
                hurt_owner_after: -Fix::ONE,
                can_hurt_owner: source.can_hurt_owner,
                magnet_holder: None,
                magnet_hold_ticks: -1,
                duplicated: true,
                duplicate_lifespan: 1800,
                duplicate_shake_offset: Vec2::ZERO,
            };
            if let Some(free) = free {
                self.arrows[free] = clone;
            } else {
                self.arrows.push(clone);
            }
        }
    }

    fn duplicate_ability_pickup(
        &mut self,
        source_index: usize,
        direction: Vec2,
        data: &data::RolloutData,
    ) {
        let source = self.ability_pickups[source_index];
        let speed = source.body.velocity.length() + Fix::from_int(15);
        for clone_index in 0..3 {
            let position = Self::fan_out(
                3,
                direction,
                source.position,
                Fix::from_int(2) * source.scale,
                Fix::ONE,
                clone_index,
            );
            let hierarchy_base = self.next_spawn_hierarchy;
            self.next_spawn_hierarchy += data.pickup.updatable_count;
            let mut body = data.pickup.body;
            body.velocity = (position - source.position).normalized_safe() * speed;
            body.orientation = source.body.orientation;
            let clone = AbilityPickup {
                active: true,
                born_tick: self.tick,
                updater_tick: u32::MAX,
                hierarchy_base,
                entity: None,
                ability: source.ability,
                position,
                scale: source.scale,
                body,
                enabled: false,
                time_passed: Fix::ZERO,
                time_since_swap: Fix::ZERO,
                previous_vibration: Vec2::ZERO,
                duplicated: true,
                duplicate_lifespan: 1800,
                duplicate_shake_offset: Vec2::ZERO,
            };
            if let Some(free) = self
                .ability_pickups
                .iter()
                .position(|pickup| !pickup.active)
            {
                self.ability_pickups[free] = clone;
            } else {
                self.ability_pickups.push(clone);
            }
        }
    }

    fn duplicate_black_hole(
        &mut self,
        source_index: usize,
        direction: Vec2,
        data: &data::RolloutData,
    ) {
        let source = self.black_holes[source_index];
        let position = source.position + direction * source.radius * Fix::from_int(2);
        let hierarchy_base = self.next_spawn_hierarchy;
        self.next_spawn_hierarchy += data.black_hole.updatable_count;
        let target_size = Fix::from_int(100) + source.mass.abs() * data.black_hole.growth;
        // The clone's BlackHole.Init runs with the next pass's new updatables,
        // which is when its circle registers (register_pending_black_holes).
        // SetMass(source) leaves the unset velocity at zero, then
        // AddForce(mass * dir * 6) divides the mass back out.
        let velocity = if source.mass == Fix::ZERO {
            Vec2::ZERO
        } else {
            source.mass * direction * Fix::from_int(6) / source.mass
        };
        let clone = BlackHoleState {
            active: true,
            born_tick: self.tick,
            entity: None,
            hierarchy_base,
            owner: 0,
            position,
            velocity,
            mass: source.mass,
            time_since_growth: Fix::ZERO,
            previous_target_size: Fix::from_int(100),
            target_size,
            radius: Fix::ZERO,
            start_radius: source.collider_start_radius,
            collider_start_radius: Fix::ZERO,
            duplicated: true,
            duplicate_lifespan: 480,
            duplicate_shake_offset: Vec2::ZERO,
        };
        self.pending_black_holes.push(clone);
    }

    fn register_pending_black_holes(&mut self, data: &data::RolloutData) {
        for mut hole in std::mem::take(&mut self.pending_black_holes) {
            hole.radius =
                Self::black_hole_initial_radius(hole.start_radius, hole.target_size, data);
            hole.collider_start_radius = hole.radius;
            let entity = self.entities.len();
            let id = self.next_id();
            self.entities.push(CEntity {
                id,
                kind: 0,
                layer: data.black_hole.layer,
                flags: E_ACTIVE | E_ENABLED | E_TRIGGER,
                hierarchy: 100_000_000
                    + hole.hierarchy_base
                    + data.black_hole.hole_collider_hierarchy,
                x: hole.position.x.raw(),
                y: hole.position.y.raw(),
                radius: hole.radius.raw(),
                inverse_mass: -Fix::ONE.raw(),
                ..CEntity::default()
            });
            hole.entity = Some(entity);
            if let Some(free) = self.black_holes.iter().position(|hole| !hole.active) {
                self.black_holes[free] = hole;
            } else {
                self.black_holes.push(hole);
            }
        }
    }

    fn duplicate_player_target(
        &mut self,
        victim: usize,
        _hit_position: Vec2,
        direction: Vec2,
        data: &data::RolloutData,
    ) {
        if self.players[victim].active == ActiveAbility::Rock {
            let source_position = self.players[victim].base.position;
            let source = self.players[victim].rock;
            let position = source_position + direction * Fix::from_int(4) * source.scale;
            let mut body = data.rock.body;
            body.velocity = (position - source_position).normalized_safe()
                * (source.body.velocity.length() + Fix::from_int(15));
            body.orientation = source.body.orientation;
            let entity = self.entities.len();
            let id = self.next_id();
            self.entities.push(CEntity {
                id,
                kind: 0,
                layer: 16,
                owner: self.players[victim].base.id,
                flags: E_ACTIVE | E_ENABLED,
                hierarchy: 100_000_000 + self.next_spawn_hierarchy + 3,
                x: position.x.raw(),
                y: position.y.raw(),
                vx: body.velocity.x.raw(),
                vy: body.velocity.y.raw(),
                radius: (data.rock.radius * source.scale).raw(),
                rotation: body.orientation.raw(),
                angular_velocity: body.angular_velocity.raw(),
                inverse_mass: body.inverse_mass.raw(),
                ..CEntity::default()
            });
            self.next_spawn_hierarchy += 4;
            let clone = DuplicatedRock {
                active: true,
                born_tick: self.tick,
                entity: Some(entity),
                owner: victim,
                position,
                body,
                scale: source.scale,
                duplicate_lifespan: 1800,
                duplicate_shake_offset: Vec2::ZERO,
            };
            if let Some(free) = self.duplicated_rocks.iter().position(|rock| !rock.active) {
                self.duplicated_rocks[free] = clone;
            } else {
                self.duplicated_rocks.push(clone);
            }
            return;
        }

        // SpawnAbilityLessClone rejects the seventeenth clone for an owner.
        if self
            .abilityless_clones
            .iter()
            .filter(|clone| clone.active && clone.owner == victim)
            .count()
            >= 16
        {
            return;
        }
        let source = self.players[victim].base.clone();
        // SlimeController.CurrentNormal reads the slime's own body, which a
        // form leaves grounded where it was entered.
        let (slime_ground, slime_position) = if self.players[victim].active == ActiveAbility::None {
            (source.ground.filter(|_| source.grounded), source.position)
        } else {
            (self.players[victim].ability_origin_ground, self.players[victim].ability_origin)
        };
        let current_normal = slime_ground
            .and_then(|ground| {
                self.platforms
                    .iter()
                    .find(|platform| platform.id == ground)
                    .map(|platform| platform.surface.normal(slime_position))
            })
            .unwrap_or(Vec2::UP);
        let launch_direction = if direction == current_normal {
            direction
        } else {
            slerp(direction, current_normal, Fix::from_f32(0.3))
        };
        let hierarchy_base = self.next_spawn_hierarchy;
        self.next_spawn_hierarchy += 8;
        let position = source.position;
        let collider = OrientedBox::from_basis(position, Vec2::RIGHT, data.player.hurtbox_extents);
        let base = Player {
            alive: true,
            out_of_bounds: false,
            id: source.id,
            position,
            rotation: Fix::ZERO,
            up: Vec2::UP,
            velocity: launch_direction * Fix::from_f64(1.3) * data.player.constants.jump_strength,
            external_velocity: Vec2::ZERO,
            radius: data.player.radius,
            space: data.maps[self.map].level_type == 2,
            scale: Fix::ONE,
            grounded: false,
            ground: None,
            local: Fix::ZERO,
            grounded_speed: Fix::ZERO,
            previous_jump: false,
            skip_next_gravity: false,
            instant_cast_this_pass: false,
            was_upside_down: false,
            pre_move_up: Vec2::UP,
            pre_move_grounded: false,
            attach_upside_down: None,
            jumped_this_frame: false,
            constants: data.player.constants.clone(),
            cooldown: Fix::ZERO,
            dash: DashState::default(),
            collider,
            collider_rotation: Fix::ZERO,
            collider_inverse_extents: Vec2::ZERO,
            collider_basis: Vec2::RIGHT,
            aligned: None,
            input_normalized: None,
        };
        let clone = AbilitylessClone {
            active: true,
            born_tick: self.tick,
            hierarchy_base,
            entity: None,
            owner: victim,
            base,
            obs_state: STATE_FALL,
            state_ticks: 0,
            facing_right: true,
            prev_input_align: Fix::ZERO,
            captured_by_ball: None,
            poke_invulnerable: false,
            blink_tunnel_active: false,
            blink_tunnel_born_tick: 0,
            blink_tunnel_age: Fix::ZERO,
            blink_tunnel_released: false,
            blink_reactivated_tick: None,
            late_pull: Vec2::ZERO,
            ground_destroyed: false,
        };
        if let Some(free) = self
            .abilityless_clones
            .iter()
            .position(|clone| !clone.active)
        {
            if let Some(e) = self.abilityless_clones[free].entity
                && self.entities[e].flags & E_DESTROYED != 0
            {
                self.entities[e].flags = E_REMOVED;
            }
            self.abilityless_clones[free] = clone;
        } else {
            self.abilityless_clones.push(clone);
        }
    }

