    #[test]
    #[cfg(feature = "q32")]
    fn circle_scale_ratio_preserves_source_fix_grouping() {
        let radius = Fix::from_raw(5_302_428_003);
        let previous = Fix::from_raw(1_000_000_000);
        let scale = Fix::from_raw(2_000_000_000);

        assert_eq!(
            (radius * ((Fix::ONE / previous) * scale)).raw(),
            10_604_856_006
        );
        assert_eq!(((radius / previous) * scale).raw(), 10_604_856_005);
    }

    #[test]
    fn match_result_consumes_deaths_on_the_following_tick() {
        let mut world = RolloutWorld::new();
        let mut config = test_config();
        config.stocks = 0;
        world.reset(&config).unwrap();

        world.kill(0, ENVIRONMENT, CAUSE_ACCIDENT, true, true);
        assert!(
            !world.terminal,
            "a collision death must not end its own updater pass"
        );

        world.session_tick();
        assert!(
            !world.terminal,
            "post-physics session work must not observe a same-pass death"
        );

        world.session_result_tick();
        assert!(world.terminal);
        assert!(world.players[1].won);
    }

